-- S8 修复：电影子目录 Folder 行预建 + parent 下沉 + 祖先链
-- 生成器：tests/perf/gen-movie-subfolders.ps1（扫描安全：父链深度=磁盘深度）
CREATE TEMP TABLE subfolders (folder_guid uuid, name text, path text, top_path text);
CREATE TEMP TABLE reparent (movie_id bigint, sub_path text);
SELECT s.folder_guid, 1, 'MediaBrowser.Controller.Entities.Folder', s.name, s.path, true, '{}'::jsonb, s.name, f.id, replace(f.guid::text, '-', '')
FROM subfolders s JOIN media_items f ON f.type = 1 AND f.path = s.top_path;
UPDATE media_items m SET parent_id = sf.id
FROM reparent r, media_items sf WHERE m.id = r.movie_id AND sf.path = r.sub_path AND sf.type = 1;
DELETE FROM ancestor_ids a USING reparent r, subfolders s
WHERE a.item_id = r.movie_id AND s.path = r.sub_path AND a.ancestor_id IN (SELECT f.id FROM media_items f WHERE f.type = 1 AND f.path IN (SELECT top_path FROM subfolders));
SELECT r.movie_id, sf.id, 1 FROM reparent r JOIN media_items sf ON sf.path = r.sub_path AND sf.type = 1 ON CONFLICT DO NOTHING;
SELECT r.movie_id, f.id, 2 FROM reparent r JOIN subfolders s ON s.path = r.sub_path JOIN media_items f ON f.type = 1 AND f.path = s.top_path ON CONFLICT DO NOTHING;
SELECT sf.id, f.id, 1 FROM subfolders s JOIN media_items sf ON sf.path = s.path AND sf.type = 1 JOIN media_items f ON f.type = 1 AND f.path = s.top_path ON CONFLICT DO NOTHING;
SELECT sf.id, 1, 0 FROM subfolders s JOIN media_items sf ON sf.path = s.path AND sf.type = 1 ON CONFLICT DO NOTHING;
SELECT 'subfolder_rows' AS check, count(*) FROM media_items WHERE type = 1 AND guid IN (SELECT folder_guid FROM subfolders);
SELECT 'movie_reparented', count(*) FROM media_items m JOIN reparent r ON r.movie_id = m.id JOIN media_items p ON p.id = m.parent_id WHERE p.type = 1 AND p.guid IN (SELECT folder_guid FROM subfolders);
SELECT 'movie_depth_ok', count(*) FROM media_items m JOIN media_items p ON p.id = m.parent_id WHERE m.type = 2 AND position(p.path || '\' in m.path) = 1;
SELECT 'movie_total', count(*) FROM media_items WHERE type = 2;
